// =====================================================
// 1. 데이터 가져오기
// =====================================================

const driveItems = $('Google Drive Trigger').all();

const normalizationRulesRaw =
  $('정규화 사전 묶기').first().json.normalizationRules || [];

const classificationRulesRaw =
  $('분류 규칙 묶기').first().json.classificationRules || [];

// enabled=true만 사용
const normalizationRules = normalizationRulesRaw.filter(
  r => r.enabled === true
);

const classificationRules = classificationRulesRaw.filter(
  r => r.enabled === true
);


// =====================================================
// 2. 공통 함수
// =====================================================

function escapeRegex(text) {
  return String(text).replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
}

function replaceLiteral(text, input, output) {
  return String(text).replace(
    new RegExp(escapeRegex(input), 'gi'),
    output
  );
}

function removeLiteral(text, input) {
  return String(text).replace(
    new RegExp(escapeRegex(input), 'gi'),
    ' '
  );
}


// =====================================================
// 3. 규칙 그룹
// =====================================================

const toolRules = normalizationRules
  .filter(r => r.category === 'tool')
  .sort((a, b) => String(b.input).length - String(a.input).length);

const documentTypeRules = normalizationRules
  .filter(r => r.category === 'document_type')
  .sort((a, b) => String(b.input).length - String(a.input).length);

const versionRules = normalizationRules
  .filter(r => r.category === 'version')
  .sort((a, b) => String(b.input).length - String(a.input).length);

const canonicalTools = [
  ...new Set(toolRules.map(r => r.output))
].sort((a, b) => b.length - a.length);


// =====================================================
// 4. 파일 하나 처리
// =====================================================

function processFile(drive) {

  // ---------------------------------------------------
  // 기본 파일 정보 + 확장자 처리
  // ---------------------------------------------------

  const originalName =
    drive.name ||
    drive.originalFilename ||
    '';

  let extension =
    drive.fileExtension ||
    '';

  // Google Docs 등 fileExtension이 없는 경우 파일명에서 추출
  if (!extension) {
    const extMatch = originalName.match(/\.([A-Za-z0-9]+)$/);

    if (extMatch) {
      extension = extMatch[1];
    }
  }

  let baseName = originalName;

  if (extension) {
    baseName = baseName.replace(
      new RegExp(`\\.${escapeRegex(extension)}$`, 'i'),
      ''
    );
  }

  const originalBaseName = baseName;


  // ---------------------------------------------------
  // 프로젝트
  // 현재는 코디세이 고정
  // ---------------------------------------------------

  const project = '코디세이';

  let working = removeLiteral(
    baseName,
    '코디세이'
  );


  // ---------------------------------------------------
  // 미션 번호
  // B1-3 / B1_3 / B1 3 → B1-3
  // ---------------------------------------------------

  let mission = '';

  const missionMatch = working.match(
    /B(\d+)[_\-\s]+(\d+)/i
  );

  if (missionMatch) {
    mission = `B${missionMatch[1]}-${missionMatch[2]}`;

    working = working.replace(
      missionMatch[0],
      ' '
    );
  }


  // ---------------------------------------------------
  // P 번호
  // p1 / P1 → P1
  // 파일명 독립 항목으로 분리
  // ---------------------------------------------------

  let part = '';

  const partMatch = working.match(
    /(?:^|[_\-\s])p(\d+)(?=$|[_\-\s])/i
  );

  if (partMatch) {
    part = `P${partMatch[1]}`;

    working = working.replace(
      partMatch[0],
      ' '
    );
  }


  // ---------------------------------------------------
  // 날짜
  // 파일명 날짜 우선
  // 없으면 Drive 업로드일
  // ---------------------------------------------------

  let detectedDate = '';
  let dateSource = '';

  // YYYYMMDD / YYYY-MM-DD / YYYY_MM_DD
  let dateMatch = working.match(
    /(?<!\d)(20\d{2})[-_.]?([01]\d)[-_.]?([0-3]\d)(?!\d)/
  );

  if (dateMatch) {
    detectedDate =
      dateMatch[1].slice(2) +
      dateMatch[2] +
      dateMatch[3];

    dateSource = 'filename';

    working = working.replace(
      dateMatch[0],
      ' '
    );
  } else {

    // YYMMDD
    dateMatch = working.match(
      /(?<!\d)(\d{2})([01]\d)([0-3]\d)(?!\d)/
    );

    if (dateMatch) {
      detectedDate =
        dateMatch[1] +
        dateMatch[2] +
        dateMatch[3];

      dateSource = 'filename';

      working = working.replace(
        dateMatch[0],
        ' '
      );
    }
  }

  // 날짜 없으면 Drive 생성일
  if (!detectedDate && drive.createdTime) {

    const created = new Date(drive.createdTime);

    const parts = new Intl.DateTimeFormat(
      'en-CA',
      {
        timeZone: 'Asia/Seoul',
        year: 'numeric',
        month: '2-digit',
        day: '2-digit',
      }
    ).formatToParts(created);

    const year = parts
      .find(p => p.type === 'year')
      .value
      .slice(2);

    const month = parts
      .find(p => p.type === 'month')
      .value;

    const day = parts
      .find(p => p.type === 'day')
      .value;

    detectedDate = `${year}${month}${day}`;
    dateSource = 'uploaded_at';
  }


  // ---------------------------------------------------
  // 버전
  // 최종 / 최종본 / 완성본 → ff
  // v1 / v2 등 유지
  // ---------------------------------------------------

  let version = '';

  for (const rule of versionRules) {

    const regex = new RegExp(
      escapeRegex(rule.input),
      'i'
    );

    if (regex.test(working)) {
      version = rule.output;

      working = working.replace(
        regex,
        ' '
      );

      break;
    }
  }

  if (!version) {

    const versionMatch = working.match(
      /(?:^|[_\-\s])(v\d+|ff)(?=$|[_\-\s])/i
    );

    if (versionMatch) {
      version = versionMatch[1].toLowerCase();

      working = working.replace(
        versionMatch[0],
        ' '
      );
    }
  }


  // ---------------------------------------------------
  // 문서유형
  // 긴 표현 우선
  // ---------------------------------------------------

  let documentType = '';

  for (const rule of documentTypeRules) {

    const regex = new RegExp(
      escapeRegex(rule.input),
      'i'
    );

    if (regex.test(working)) {
      documentType = rule.output;

      working = working.replace(
        regex,
        ' '
      );

      break;
    }
  }


  // ---------------------------------------------------
  // 도구명 표준화
  // gpt → ChatGPT
  // make → Make
  // 클로드 → Claude
  // ---------------------------------------------------

  for (const rule of toolRules) {
    working = replaceLiteral(
      working,
      rule.input,
      rule.output
    );
  }


  // ---------------------------------------------------
  // 연결 표현 정리
  // ChatGPT와Claude / Make vs n8n 등
  // ---------------------------------------------------

  if (canonicalTools.length > 0) {

    const toolPattern = canonicalTools
      .map(escapeRegex)
      .join('|');

    const connectorPattern =
      '(?:와|과|vs|VS|&|\\+|/)';

    const pairRegex = new RegExp(
      `(${toolPattern})\\s*${connectorPattern}\\s*(${toolPattern})`,
      'gi'
    );

    let previous;

    do {
      previous = working;

      working = working.replace(
        pairRegex,
        '$1-$2'
      );

    } while (previous !== working);
  }


  // ---------------------------------------------------
  // 도구명 추출
  // 독립 파일명 항목으로 분리
  // ---------------------------------------------------

  const detectedTools = [];

  for (const toolName of canonicalTools) {

    const regex = new RegExp(
      `(?:^|[_\\-\\s])(${escapeRegex(toolName)})(?=$|[_\\-\\s])`,
      'i'
    );

    if (regex.test(working)) {

      detectedTools.push(toolName);

      working = working.replace(
        regex,
        ' '
      );
    }
  }

  const detectedTool = detectedTools.join('-');


  // ---------------------------------------------------
  // 비교보고서이면 주제에서 "비교" 제거
  // ---------------------------------------------------

  if (documentType === '비교보고서') {
    working = working.replace(
      /비교/gi,
      ' '
    );
  }


  // ---------------------------------------------------
  // 주제 정리
  // ---------------------------------------------------

  working = working
    .replace(/[_\s]+/g, '-')
    .replace(/-{2,}/g, '-')
    .replace(/^[\-_.]+|[\-_.]+$/g, '');

  const topic = working;


  // ---------------------------------------------------
  // 분류
  // ---------------------------------------------------

  const classificationText = [
    originalBaseName,
    documentType,
    detectedTool,
    topic
  ]
    .join(' ')
    .toLowerCase();

  const matchedRules = classificationRules
    .filter(rule => {
      return classificationText.includes(
        String(rule.keyword).toLowerCase()
      );
    })
    .sort((a, b) => {
      return Number(a.priority) - Number(b.priority);
    });

  const strongMatches = matchedRules.filter(
    r => String(r.strength).toLowerCase() === 'strong'
  );

  let targetFolder = '00-inbox';
  let status = 'review_required';
  let matchedRule = '';
  let note = '';

  if (strongMatches.length > 0) {

    const winner = strongMatches[0];

    targetFolder = winner.target_folder;
    matchedRule = winner.keyword;
    status = 'success';

    note =
      `strong 규칙 '${winner.keyword}'에 따라 분류`;

  } else if (matchedRules.length > 0) {

    matchedRule = matchedRules
      .map(r => r.keyword)
      .join(', ');

    note =
      `weak 규칙만 감지됨 (${matchedRule})`;

  } else {

    note =
      '분류 가능한 규칙을 찾지 못함';
  }


  // ---------------------------------------------------
  // 최종 파일명
  //
  // 프로젝트_미션_P번호_문서유형_도구_주제_버전_날짜
  // ---------------------------------------------------

  const nameParts = [
    project,
    mission,
    part,
    documentType,
    detectedTool,
    topic,
    version,
    detectedDate
  ].filter(Boolean);

  const normalizedName =
    nameParts.join('_') +
    (extension ? `.${extension}` : '');


  // ---------------------------------------------------
  // 결과
  // ---------------------------------------------------

  return {
    json: {

      file_id:
        drive.id,

      original_name:
        originalName,

      normalized_name:
        normalizedName,

      detected_project:
        project,

      detected_mission:
        mission,

      detected_part:
        part,

      detected_document_type:
        documentType,

      detected_tool:
        detectedTool,

      detected_topic:
        topic,

      detected_version:
        version,

      detected_date:
        detectedDate,

      date_source:
        dateSource,

      file_extension:
        extension,

      target_folder:
        targetFolder,

      matched_rule:
        matchedRule,

      matched_rules:
        matchedRules.map(r => ({
          keyword:
            r.keyword,

          folder:
            r.target_folder,

          strength:
            r.strength,

          priority:
            r.priority
        })),

      status:
        status,

      note:
        note,

      current_parent_id:
        drive.parents?.[0] || ''
    }
  };
}


// =====================================================
// 5. 모든 파일 처리
// =====================================================

return driveItems.map(
  item => processFile(item.json)
);
